CREATE TABLE outbox(seq BIGINT AUTO_INCREMENT PRIMARY KEY,event_id CHAR(36) NOT NULL UNIQUE, topic VARCHAR(90) NOT NULL,aggregate_id VARCHAR(80) NOT NULL,payload JSON NOT NULL);
CREATE TABLE inbox(event_id CHAR(36) PRIMARY KEY);
CREATE TABLE purchases(id CHAR(36) PRIMARY KEY,owner VARCHAR(80) NOT NULL,request_key VARCHAR(80) NOT NULL,request_hash CHAR(64) NOT NULL,address VARCHAR(300) NOT NULL,recipient VARCHAR(100) NOT NULL,phone VARCHAR(18) NOT NULL,payment VARCHAR(20) NOT NULL,status VARCHAR(30) NOT NULL,total BIGINT NOT NULL DEFAULT 0,lines_json JSON NOT NULL,created TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3),UNIQUE(owner,request_key),INDEX(status,created));